const text = items[0].json.data || '';
const out = [];
for (const line of text.split(/\r?\n/)) {
  const t = line.trim();
  if (!t) continue;
  try {
    const r = JSON.parse(t);
    r._kind = 'location';
    out.push({ json: r });
  } catch (e) {}
}
return out;

function normalizeText(s){
  if (s === null || s === undefined) return s;
  s = String(s).normalize('NFKC');
  s = s.replace(/\u00A0/g,' ').replace(/[\u200B-\u200D\uFEFF]/g,'');
  return s.replace(/\s+/g,' ').trim();
}
function slugify(s){
  return normalizeText(String(s||'')).toLowerCase()
    .replace(/[^a-z0-9а-яё]+/gi,'_')
    .replace(/^_+|_+$/g,'');
}
function stripTracking(u){
  return String(u||'').replace(/[?&](utm_[^&]+|ref=[^&]+)/g,'');
}
function toNum(v){
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(',', '.'));
  return Number.isFinite(n) ? n : null;
}
const out = [];
for (const item of items){
  const r = item.json;
  const kind = r._kind;
  if (kind === 'location'){
    const city = normalizeText(r.city_raw);
    const lat = toNum(r.latitude_raw);
    const lon = toNum(r.longitude_raw);
    out.push({ json: {
      _kind: 'location',
      location_id: slugify(city),
      city, latitude: lat, longitude: lon,
      source: normalizeText(r._source || 'time-in.ru'),
      source_url: stripTracking(r._source_url),
      parser_version: String(r._parser_version || '1.0'),
      collected_at: r._collected_at
    }});
  } else if (kind === 'weather'){
    const city = normalizeText(r.city_raw);
    const location_id = slugify(city);
    const rawTime = normalizeText(r.date_raw);
    const dt = new Date(rawTime);
    const observation_time_utc = isNaN(dt.getTime()) ? null : dt.toISOString();
    const day = observation_time_utc ? observation_time_utc.slice(0,10) : 'invalid';
    out.push({ json: {
      _kind: 'weather',
      observation_id: location_id + '_' + day,
      location_id,
      city,
      latitude: toNum(r.latitude_raw),
      longitude: toNum(r.longitude_raw),
      observation_time_utc,
      temperature_2m_max: toNum(r.temperature_2m_max_raw),
      temperature_2m_min: toNum(r.temperature_2m_min_raw),
      precipitation_sum: toNum(r.precipitation_sum_raw),
      source: normalizeText(r._source || 'open_meteo'),
      source_url: stripTracking(r._source_url),
      parser_version: String(r._parser_version || '1.0'),
      collected_at: r._collected_at
    }});
  }
}
return out;

const out = [];
for (const item of items){
  const r = item.json;
  const errs = [];
  if (!r.observation_id || r.observation_id.indexOf('_') === -1) errs.push('bad observation_id');
  if (typeof r.latitude !== 'number' || r.latitude < -90 || r.latitude > 90) errs.push('latitude out of range');
  if (typeof r.longitude !== 'number' || r.longitude < -180 || r.longitude > 180) errs.push('longitude out of range');
  if (typeof r.temperature_2m_max !== 'number' || r.temperature_2m_max < -90 || r.temperature_2m_max > 60) errs.push('tmax out of range');
  if (typeof r.temperature_2m_min !== 'number' || r.temperature_2m_min < -90 || r.temperature_2m_min > 60) errs.push('tmin out of range');
  if (typeof r.temperature_2m_max === 'number' && typeof r.temperature_2m_min === 'number' && r.temperature_2m_max < r.temperature_2m_min) errs.push('tmax < tmin');
  if (r.precipitation_sum !== null && (typeof r.precipitation_sum !== 'number' || r.precipitation_sum < 0)) errs.push('precip < 0');
  if (!r.observation_time_utc) errs.push('bad date');
  else if (new Date(r.observation_time_utc).getTime() > Date.now()) errs.push('future date');
  if (!r.city || r.city.length < 2) errs.push('city too short');
  out.push({ json: Object.assign({}, r, { _valid: errs.length === 0, _reason: errs.join('; ') }) });
}
return out;
